INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloodstained: Curse of the Moon', '“Bloodstained: Curse of the Moon” is packed with the retro charm that made the legendary 2D action games of the 80s so enjoyable. Take control of one of four characters that can be interchanged at any time during gameplay: The sword-swinging exorcist Zangetsu, the whip-wielding heroine Miriam, the magic using alchemist Alfred, and Gebel, who can turn into a bat and take to the skies. Finally, you can experience multiple endings depending on how you interact with the characters you meet. This project is the 8-bit style game promised as a stretch goal of the 2015 Kickstarter campaign for "Bloodstained: Ritual of the Night." Backers of the Kickstarter campaign are encouraged to check the Kickstarter page for updates.' FROM games WHERE igdb_id = 101176 ON CONFLICT (game_id, language_code) DO NOTHING;
