INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'To Leave', 'This is an indie platformer about a boy who seeks to leave his old life behind using a magical flying door. To Leave features challenging puzzle-platformer levels that will test your puzzle-solving skills through an emotionally gripping story. The game addresses depression - a state of mind that tempts you to open any doors if they allow you to leave everything behind... sometimes for a moment... sometimes for life.' FROM games WHERE igdb_id = 61714 ON CONFLICT (game_id, language_code) DO NOTHING;
