INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ashen', 'Set in a sprawling open world, Ashen is a tight, 3rd person, skill-based action RPG about guiding your wanderer through a newly lit world. Fight alongside others, forge friendships and defeat the creatures of shadow determined to cast the world back into darkness. Explore mysterious dungeons, fight epic bosses and explore diverse regions filled with gorgeous vistas and mythical creatures. Meet characters along the way who will join you on your journey and turn your home into a lively town. In this new era of light, you must protect the Ashen and destroy the hungering shadows once and for all.' FROM games WHERE igdb_id = 17001 ON CONFLICT (game_id, language_code) DO NOTHING;
